ing? // JSON 数组\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  eaConfigModules EAConfigModule[]\n\n  @@index([category])\n}\n\nmodel EAConfig {\n  id          String   @id @default(cuid())\n  userId      String\n  name        String\n  description String?\n  configJson  String\n  version     Int      @default(1)\n  isPublished Boolean  @default(false)\n  isTemplate  Boolean  @default(false)\n  usageCount  Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  modules     EAConfigModule[]\n  runSessions EARunSession[]\n\n  @@index([userId])\n  @@index([isPublished])\n}\n\nmodel EAConfigModule {\n  id         String  @id @default(cuid())\n  eaConfigId String\n  moduleId   String\n  parameters String?\n  enabled    Boolean @default(true)\n  priority   Int     @default(0)\n\n  eaConfig EAConfig @relation(fields: [eaConfigId], references: [id], onDelete: Cascade)\n  module   Module   @relation(fields: [moduleId], references: [id])\n\n  @@unique([eaConfigId, moduleId])\n}\n\nmodel EARunSession {\n  id             String   @id @default(cuid())\n  eaConfigId     String\n  name           String\n  runMode        String // simulation | live\n  status         String // running | stopped | completed\n  symbol         String\n  timeframe      String\n  initialCapital Float?\n  totalPnl       Float    @default(0)\n  totalTrades    Int      @default(0)\n  winRate        Float    @default(0)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  eaConfig  EAConfig     @relation(fields: [eaConfigId], references: [id], onDelete: Cascade)\n  runLogs   EARunLog[]\n  positions EAPosition[]\n\n  @@index([eaConfigId])\n  @@index([status])\n}\n\nmodel EARunLog {\n  id         String   @id @default(cuid())\n  sessionId  String\n  timestamp  DateTime @default(now())\n  level      String // info|signal|risk|exec|warn|error\n  moduleName String?\n  message    String\n\n  session EARunSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  @@index([sessionId])\n}\n\nmodel EAPosition {\n  id           String    @id @default(cuid())\n  sessionId    String\n  ticket       String\n  symbol       String\n  type         String // buy | sell\n  volume       Float\n  openPrice    Float\n  currentPrice Float     @default(0)\n  stopLoss     Float?\n  takeProfit   Float?\n  pnl          Float     @default(0)\n  status       String // open | closed\n  openedAt     DateTime  @default(now())\n  closedAt     DateTime?\n\n  session EARunSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  @@index([sessionId])\n  @@index([status])\n}\n\n// ============================================================\n// 模块 Z: 开源合规再分发 (路径 D - task-0037 plan-0034 落地)\n// ============================================================\n// 战略: 不走净室重写伪合规路径, 走 GPL-3 §4 合规再分发\n// X 池 8,534 文件 → 注入 + 双署名 + 付费会员门控\n// 铁律 #283 (默认拒绝) / #284 (不透明主键代理) / #285 (商品溯源无真空)\n\nenum OpenSourceLicense {\n  GPL_2\n  GPL_3\n  APACHE_2_0\n  MIT\n  BSD_3\n  UNLICENSE\n  LGPL\n  MPL_2_0\n  PROPRIETARY\n  NO_LICENSE\n  UNKNOWN\n}\n\nenum OpenSourceAccessAction {\n  VIEW\n  DOWNLOAD\n  LIKE\n  UPGRADE_CLICK\n  VIEW_PAID_REQUIRED // task056 Phase 7: 白嫖拦截埋点\n}\n\nmodel OpenSourceRelease {\n  id              String            @id @default(cuid())\n  // 关联 Product (升级目标, 可空: 有的开源版无对应付费版)\n  productId       String?           @unique\n  // master.db.mql_files.file_id (D:\\... 全路径, 铁律 #284 不透明主键)\n  sourceFileId    String\n  license         OpenSourceLicense\n  // 双署名用: 原作者 + 原始仓库\n  originalAuthor  String\n  originalSource  String // \"github\" / \"algo-forge\" / ...\n  // 展示\n  title           String\n  description     String?\n  // 注入后产物 (cpro_patched_redistribute/ 隔离目录)\n  fileUrl         String\n  originalFileUrl String?\n  // 评分/标签\n  tier            String?\n  // 门控: 默认需要 MONTHLY 付费会员\n  requiredPlan    MembershipPlan    @default(MONTHLY)\n  isFeatured      Boolean           @default(false)\n  downloadCount   Int               @default(0)\n  viewCount       Int               @default(0)\n  publishedAt     DateTime?\n  createdAt       DateTime          @default(now())\n  updatedAt       DateTime          @updatedAt\n\n  // 关系\n  product            Product?              @relation(fields: [productId], references: [id], onDelete: SetNull)\n  accessLogs         OpenSourceAccessLog[]\n  openSourceTutorial OpenSourceTutorial?\n\n  @@index([license])\n  @@index([originalSource])\n  @@index([requiredPlan])\n  @@index([isFeatured, publishedAt])\n  @@index([publishedAt])\n}\n\nmodel OpenSourceAccessLog {\n  id        String                 @id @default(cuid())\n  userId    String? // 可空: 匿名浏览 (前 12 个公开预览)\n  releaseId String\n  action    OpenSourceAccessAction\n  ipAddress String?\n  userAgent String?\n  referrer  String?\n  createdAt DateTime               @default(now())\n\n  // 关系\n  user    User?             @relation(fields: [userId], references: [id], onDelete: SetNull)\n  release OpenSourceRelease @relation(fields: [releaseId], references: [id], onDelete: Cascade)\n\n  @@index([userId, action])\n  @@index([releaseId, action])\n  @@index([createdAt])\n}\n\nmodel UpgradeConversion {\n  id            String   @id @default(cuid())\n  userId        String\n  fromReleaseId String? // 可空: 直接付费 (无开源版触发)\n  toProductId   String\n  convertedAt   DateTime @default(now())\n\n  // 关系\n  user      User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  toProduct Product @relation(fields: [toProductId], references: [id], onDelete: Cascade)\n\n  @@index([userId, convertedAt])\n  @@index([fromReleaseId])\n  @@index([toProductId])\n}\n\n// ============================================================\n// 模块 Z2: 投研研报 (Phase 6.2 教程内容引擎)\n// ============================================================\n\nenum TutorialStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\nmodel OpenSourceTutorial {\n  id             String         @